#!/usr/bin/env bash
set -euo pipefail
source "$(dirname "$0")/common.sh"
heading 'Paso 93 — precargar operación Gold variada'
Q() { bq --project_id="$PROJECT_ID" --location="$REGION" query --use_legacy_sql=false --maximum_bytes_billed=524288000 "$1" >/dev/null; }

Q "UPDATE \`$PROJECT_ID.$GOLD_DATASET.dim_productos\` SET category_name=CASE MOD(ABS(FARM_FINGERPRINT(sku_id)),6) WHEN 0 THEN 'Abarrotes' WHEN 1 THEN 'Bebidas' WHEN 2 THEN 'Lácteos' WHEN 3 THEN 'Limpieza' WHEN 4 THEN 'Cuidado personal' ELSE 'Hogar' END WHERE status='ACTIVE'"
Q "INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu01_riesgo_quiebre_despacho\` SELECT 'load-20261119',p.ids[OFFSET(MOD(n,ARRAY_LENGTH(p.ids)))],s.ids[OFFSET(MOD(n*37,ARRAY_LENGTH(s.ids)))],ROUND(MOD(ABS(FARM_FINGERPRINT(CAST(n AS STRING))),100)/100,4),CAST(MOD(ABS(FARM_FINGERPRINT(CAST(n*7 AS STRING))),520) AS INT64),IF(MOD(n,11)=0,'REPOSICIONAR/DESPACHAR',IF(MOD(n,7)=0,'PRIORIZAR','MONITOREAR')),TIMESTAMP_SUB(CURRENT_TIMESTAMP(),INTERVAL MOD(n,72) HOUR) FROM UNNEST(GENERATE_ARRAY(1,50000)) n CROSS JOIN (SELECT ARRAY_AGG(sku_id ORDER BY sku_id) ids FROM \`$PROJECT_ID.$GOLD_DATASET.dim_productos\`) p CROSS JOIN (SELECT ARRAY_AGG(store_id ORDER BY store_id) ids FROM \`$PROJECT_ID.$GOLD_DATASET.dim_tiendas\`) s"
Q "INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu02_plan_reposicion\` SELECT 'load-20261119',p.ids[OFFSET(MOD(n,ARRAY_LENGTH(p.ids)))],w.ids[OFFSET(MOD(n*11,ARRAY_LENGTH(w.ids)))],DATE_ADD(CURRENT_DATE(),INTERVAL MOD(n,14) DAY),CAST(20+MOD(n*13,480) AS INT64),CAST(10+MOD(n*7,360) AS INT64),IF(MOD(n,9)=0,'HIGH',IF(MOD(n,4)=0,'MEDIUM','NORMAL')) FROM UNNEST(GENERATE_ARRAY(1,30000)) n CROSS JOIN (SELECT ARRAY_AGG(sku_id ORDER BY sku_id) ids FROM \`$PROJECT_ID.$GOLD_DATASET.dim_productos\`) p CROSS JOIN (SELECT ARRAY_AGG(warehouse_id ORDER BY warehouse_id) ids FROM \`$PROJECT_ID.$GOLD_DATASET.dim_almacenes\`) w"
Q "INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu04_alertas_mantenimiento\` SELECT 'load-20261119',CONCAT('ASSET-',LPAD(CAST(MOD(n,1200)+1 AS STRING),4,'0')),CONCAT('SENSOR-',LPAD(CAST(MOD(n,4800)+1 AS STRING),4,'0')),w.ids[OFFSET(MOD(n,ARRAY_LENGTH(w.ids)))],IF(MOD(n,6)=0,'TEMPERATURA_ANOMALA',IF(MOD(n,5)=0,'VIBRACION_ELEVADA','LECTURA_SENSOR')),IF(MOD(n,13)=0,'HIGH',IF(MOD(n,4)=0,'MEDIUM','NORMAL')),ROUND(1+MOD(n*17,990)/100,2),TIMESTAMP_SUB(CURRENT_TIMESTAMP(),INTERVAL MOD(n,96) HOUR) FROM UNNEST(GENERATE_ARRAY(1,15000)) n CROSS JOIN (SELECT ARRAY_AGG(warehouse_id ORDER BY warehouse_id) ids FROM \`$PROJECT_ID.$GOLD_DATASET.dim_almacenes\`) w"
Q "INSERT INTO \`$PROJECT_ID.$GOLD_DATASET.cu03_kpis_operativos\` VALUES ('load-20261119',CURRENT_DATE(),'streaming',CAST(180000+MOD(ABS(FARM_FINGERPRINT(CAST(CURRENT_DATE() AS STRING))),70000) AS INT64),CAST(520000+MOD(ABS(FARM_FINGERPRINT(CAST(CURRENT_DATE() AS STRING))),210000) AS INT64),0.18,125000,0.96)"
Q "CREATE OR REPLACE TABLE \`$PROJECT_ID.$GOLD_DATASET.agg_inventario_resumen\` AS SELECT COUNT(*) AS risk_rows,COUNT(DISTINCT sku_id) AS at_risk_skus,COUNT(DISTINCT store_id) AS affected_stores,COUNTIF(risk_score>=0.5 OR STARTS_WITH(recommended_action,'REPOSICIONAR')) AS critical_skus,CURRENT_TIMESTAMP() AS refreshed_at FROM \`$PROJECT_ID.$GOLD_DATASET.cu01_riesgo_quiebre_despacho\`"
echo 'SCRIPT 93: 1'
echo 'Datos Gold variados cargados: riesgos, reposición, mantenimiento y KPIs.'
